import * as T from './vendor/three/three.module.js';
import {GLTFLoader} from './vendor/three/loaders/GLTFLoader.js';
const scene=new T.Scene();scene.background=new T.Color('#dae3e7');
const renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;document.body.prepend(renderer.domElement);
const camera=new T.PerspectiveCamera(42,innerWidth/innerHeight,.05,80);scene.add(new T.HemisphereLight('#f2f7ff','#a5a292',2.5));const sun=new T.DirectionalLight('#fff0d7',2.7);sun.position.set(3,7,5);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);scene.add(sun);
const floor=new T.Mesh(new T.PlaneGeometry(60,60),new T.MeshStandardMaterial({color:'#c6d1d1',roughness:.9}));floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;scene.add(floor);const grid=new T.GridHelper(30,60,'#8a9fa7','#b2c0c3');grid.position.y=.002;scene.add(grid);
const root=new T.Group();scene.add(root);let model,mixer,actions,current,shoes=[],paused=false,rate=1,time=0,travel=0,angle=0,elev=.15,radius=4.8,drag=false,lx=0,ly=0,phase='walk';
const ui=id=>document.getElementById(id),v=new T.Vector3(),box=new T.Box3();
function soleBounds(){let lo=Infinity,hi=-Infinity;model.updateMatrixWorld(true);model.traverse(o=>{if(o.isSkinnedMesh)o.skeleton.update();});for(const mesh of shoes){mesh.computeBoundingBox();box.copy(mesh.boundingBox).applyMatrix4(mesh.matrixWorld);lo=Math.min(lo,box.min.y);hi=Math.max(hi,box.min.y);}return {lo,hi};}
function play(name,fade=.25){if(current===name)return;const old=actions[current];if(old)old.fadeOut(fade);const action=actions[name].reset().stopFading().setEffectiveWeight(1);if(fade>0)action.fadeIn(fade);action.play();current=name;}
try{const gltf=await new GLTFLoader().loadAsync('./assets/characters/coach-sam.glb');model=gltf.scene;model.traverse(o=>{if(o.isMesh){o.castShadow=o.receiveShadow=true;if(o.name==='shoes01')shoes.push(o);}});root.add(model);mixer=new T.AnimationMixer(model);actions=Object.fromEntries(gltf.animations.map(c=>[c.name,mixer.clipAction(c)]));actions.Idle_Standing.play();mixer.update(0);box.setFromObject(model);const scale=1.78/(box.max.y-box.min.y);model.scale.multiplyScalar(scale);model.position.y=-box.min.y*scale;mixer.stopAllAction();play(ui('clip').value,0);mixer.update(0);ui('status').hidden=true;ui('scan').disabled=false;}catch(e){ui('status').textContent='加载失败：'+e.message;console.error(e);}
function reset(){time=0;travel=0;root.position.set(0,0,0);root.rotation.y=0;phase='walk';if(mixer){mixer.stopAllAction();current=null;play(ui('clip').value,0);}}
ui('clip').onchange=reset;ui('motion').onchange=reset;ui('rate').onchange=e=>rate=Number(e.target.value);ui('pause').onclick=()=>{paused=!paused;ui('pause').textContent=paused?'继续':'暂停';};
function update(dt){if(!mixer)return;time+=dt;const mode=ui('motion').value,name=ui('clip').value;const nominal=name==='Walk_Relaxed'?1.30:name==='Jog'?2.79:name==='Walk_Brisk'?1.69:0;let moving=mode!=='stationary'&&nominal>0;
 if(mode==='stop'){moving=moving&&time%8<5;play(moving?name:'Idle_Standing');}else play(name);
 if(moving){travel+=dt*nominal;if(mode==='circle'){root.position.set(Math.sin(travel/2)*2,0,Math.cos(travel/2)*2-2);root.rotation.y=travel/2+Math.PI/2;}else{const t=travel%8;root.position.z=t<4?t-2:6-t;root.rotation.y=t<4?0:Math.PI;}}
 mixer.update(dt);phase=moving?'移动':mode==='stationary'?'原地动作':'站立';}
function render(){camera.position.set(root.position.x+Math.sin(angle)*radius,1.15+Math.sin(elev)*radius,root.position.z+Math.cos(angle)*radius);camera.lookAt(root.position.x,.95,root.position.z);renderer.render(scene,camera);if(model){const soles=soleBounds();ui('metrics').textContent=`${current}\n时间 ${actions[current].time.toFixed(2)} s\n状态 ${phase}\n根位置 ${root.position.x.toFixed(2)}, ${root.position.z.toFixed(2)} m\n最低鞋底 ${(soles.lo*100).toFixed(1)} cm\n动作倍率 ${rate}×`;}}
ui('step').onclick=()=>{paused=true;ui('pause').textContent='继续';update(1/60);render();};
ui('scan').onclick=()=>{paused=true;ui('pause').textContent='继续';const name=ui('clip').value;root.position.set(0,0,0);root.rotation.y=0;mixer.stopAllAction();current=null;play(name,0);const action=actions[name],duration=action.getClip().duration;let low=Infinity,high=-Infinity;const positions=[],feet=[];const left=model.getObjectByName('foot_l'),right=model.getObjectByName('foot_r');const pelvis=model.getObjectByName('pelvis');for(let i=0;i<=60;i++){action.time=duration*i/60;mixer.update(0);const foot=soleBounds();low=Math.min(low,foot.lo);high=Math.max(high,foot.lo);if(pelvis){pelvis.getWorldPosition(v);positions.push(v.clone());}if(left&&right)feet.push([left.getWorldPosition(new T.Vector3()),right.getWorldPosition(new T.Vector3())]);}
 const drift=positions.length?Math.max(...positions.map(p=>Math.hypot(p.x-positions[0].x,p.z-positions[0].z))):0;
 const speeds=[];for(let i=1;i<feet.length;i++)for(let side=0;side<2;side++){const a=feet[i-1][side],b=feet[i][side],other=feet[i][1-side];if(b.y<=other.y+.005){const speed=-(b.z-a.z)/(duration/60);if(speed>.02)speeds.push(speed);}}speeds.sort((a,b)=>a-b);const stanceSpeed=speeds.length?speeds[Math.floor(speeds.length/2)]:0;ui('result').textContent=`支撑脚后移速度中位数 ${stanceSpeed.toFixed(2)} m/s（用于步速校准）。周期 ${duration.toFixed(2)} s，61 个采样。最低鞋底范围 ${(low*100).toFixed(1)}～${(high*100).toFixed(1)} cm；髋部水平偏移最大 ${(drift*100).toFixed(1)} cm。负值代表穿地；这些数据不单独证明步态自然。`;action.time=0;mixer.update(0);render();};
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{angle={front:0,side:Math.PI/2,back:Math.PI}[b.dataset.view];render();};
renderer.domElement.onpointerdown=e=>{drag=true;lx=e.clientX;ly=e.clientY;renderer.domElement.setPointerCapture(e.pointerId);};renderer.domElement.onpointermove=e=>{if(drag){angle-=(e.clientX-lx)*.006;elev=Math.max(-.05,Math.min(.8,elev+(e.clientY-ly)*.003));lx=e.clientX;ly=e.clientY;}};renderer.domElement.onpointerup=renderer.domElement.onpointercancel=()=>drag=false;
let previous=0;renderer.setAnimationLoop(now=>{const dt=Math.min((now-previous)/1000||.016,.04);previous=now;if(!paused)update(dt*rate);render();});addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});
